WITH RECURSIVE x8 AS (SELECT 0 UNION ALL SELECT x7.v50923 + 1 FROM x11 WHERE x7.v50923 < 19) SELECT x7.v50923, x7.v50923, ST_CROSSES(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x4, x7.v50923 FROM v50922 AS x7 WHERE EXTRACT(MONTH FROM x7.v50923) = 1 AND EXTRACT(YEAR FROM x7.v50923) = 2001